from typing import Callable, Dict, Hashable, Sequence, Tuple

def max_fiber(f: Callable[[Hashable], Hashable],
              support: Sequence[Hashable]) -> Tuple[int, bool]:
    counts: Dict[Hashable, int] = {}
    for x in support:
        y = f(x)
        counts[y] = counts.get(y, 0) + 1
    m = max(counts.values()) if counts else 0
    return m, m <= 1

algorithms.pseudocode:
function MAX_FIBER(f, support):
    counts <- empty map
    for each x in support:
        counts[f(x)] <- counts.get(f(x), 0) + 1
    m <- max value in counts
    return (m, m <= 1)   # (max fiber size, is_injective)

