import math, random
from typing import Callable, Dict, Hashable, List, Sequence

def shannon_entropy(p: Sequence[float]) -> float:
    return -sum(px * math.log(px) for px in p if px > 0.0)

def pushforward_entropy(f: Callable[[Hashable], Hashable],
                        support: Sequence[Hashable], p: Sequence[float]) -> float:
    img: Dict[Hashable, float] = {}
    for x, px in zip(support, p):
        img[f(x)] = img.get(f(x), 0.0) + px
    return shannon_entropy(list(img.values()))

def random_distribution(n: int, rng: random.Random) -> List[float]:
    raw = [rng.random() + 1e-9 for _ in range(n)]
    s = sum(raw)
    return [r / s for r in raw]

def demo() -> None:
    rng = random.Random(2024)
    support = list(range(6))
    f = lambda x: x % 3  # merges fibers (non-injective)
    for _ in range(5):
        p = random_distribution(len(support), rng)
        hp, hfp = shannon_entropy(p), pushforward_entropy(f, support, p)
        assert hp - hfp >= -1e-12, "DPI violated"
        print(f"H(p)={hp:.4f}  H(f_*p)={hfp:.4f}  gap={hp-hfp:.4f} >= 0")

if __name__ == "__main__":
    demo()

import itertools, math, random
from typing import Callable, Dict, Hashable, List, Sequence, Tuple

K, T = 1.380649e-23, 300.0  # Boltzmann constant (J/K), room temperature (K)

def shannon_entropy(p: Sequence[float]) -> float:
    return -sum(px * math.log(px) for px in p if px > 0.0)

def landauer_work(f: Callable[[Hashable], Hashable],
                  support: Sequence[Hashable], p: Sequence[float]) -> float:
    img: Dict[Hashable, float] = {}
    for x, px in zip(support, p):
        img[f(x)] = img.get(f(x), 0.0) + px
    return K * T * (shannon_entropy(p) - shannon_entropy(list(img.values())))

def cnot(a: int, b: int) -> Tuple[int, int]:
    return (a, a ^ b)

def toffoli(a: int, b: int, c: int) -> Tuple[int, int, int]:
    return (a, b, c ^ (a & b))

def fredkin(a: int, b: int, c: int) -> Tuple[int, int, int]:
    return (a, c, b) if a == 1 else (a, b, c)

def demo() -> None:
    b2 = list(itertools.product([0, 1], repeat=2))
    b3 = list(itertools.product([0, 1], repeat=3))
    assert all(cnot(*cnot(a, b)) == (a, b) for a, b in b2)
    assert all(toffoli(*toffoli(*t)) == t for t in b3)
    assert all(fredkin(*fredkin(*t)) == t for t in b3)
    assert all(cnot(a, b)[1] == a ^ b for a, b in b2)          # XOR
    assert all(toffoli(a, b, 0)[2] == (a & b) for a, b in b2)  # AND
    rng = random.Random(99)
    raw = [rng.random() + 1e-9 for _ in b3]
    s = sum(raw)
    p3 = [r / s for r in raw]
    print("CNOT/Toffoli/Fredkin verified reversible and correct.")
    print(f"Toffoli dissipated work on random input: {landauer_work(lambda x: toffoli(*x), b3, p3):.3e} J")

if __name__ == "__main__":
    demo()
